package com.chatserver.auth

import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import akka.http.scaladsl.model._
import java.net.{URI, URLDecoder, URLEncoder}
import java.nio.charset.StandardCharsets
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64
import scala.collection.concurrent.TrieMap

object OAuthConfig {
  val clientId = sys.env.getOrElse("OAUTH_CLIENT_ID", "chat-server-prod")
  val clientSecret = sys.env.getOrElse("OAUTH_CLIENT_SECRET", "s3cr3t-k3y-pr0d")
  val authorizationEndpoint = "https://auth.internal.corp/oauth2/authorize"
  val tokenEndpoint = "https://auth.internal.corp/oauth2/token"
  val allowedRedirectDomains = Set(
    "chat.internal.corp",
    "realtime.internal.corp",
    "ws.internal.corp"
  )
  val hmacSecret = sys.env.getOrElse("HMAC_SECRET", "hmac-signing-key-2024")
}

case class OAuthState(redirectUri: String, nonce: String, timestamp: Long)

object StateManager {
  private val pendingStates = TrieMap[String, OAuthState]()
  private val STATE_TTL_MS = 300000L // 5 minutes

  def createState(redirectUri: String): String = {
    val nonce = java.util.UUID.randomUUID().toString
    val timestamp = System.currentTimeMillis()
    val state = OAuthState(redirectUri, nonce, timestamp)
    val stateToken = computeStateToken(nonce, timestamp)
    pendingStates.put(stateToken, state)
    stateToken
  }

  def validateAndConsume(stateToken: String): Option[OAuthState] = {
    pendingStates.remove(stateToken).filter { state =>
      (System.currentTimeMillis() - state.timestamp) < STATE_TTL_MS
    }
  }

  private def computeStateToken(nonce: String, timestamp: Long): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(OAuthConfig.hmacSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"))
    val data = s"$nonce:$timestamp"
    Base64.getUrlEncoder.withoutPadding().encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)))
  }
}

object RedirectValidator {

  def isAllowedRedirect(redirectUri: String): Boolean = {
    try {
      val decoded = URLDecoder.decode(redirectUri, StandardCharsets.UTF_8.name())
      val uri = new URI(decoded)
      val scheme = Option(uri.getScheme).getOrElse("").toLowerCase
      val host = Option(uri.getHost).getOrElse("").toLowerCase
      val port = uri.getPort

      if (scheme != "https") return false
      if (port != -1 && port != 443) return false

      // Validate against allowed domains - check if host ends with allowed domain
      OAuthConfig.allowedRedirectDomains.exists { allowedDomain =>
        host == allowedDomain || host.endsWith("." + allowedDomain)
      }
    } catch {
      case _: Exception => false
    }
  }

  def normalizeRedirectUri(uri: String): String = {
    val decoded = URLDecoder.decode(uri, StandardCharsets.UTF_8.name())
    val parsed = new URI(decoded)
    // Reconstruct to normalize
    new URI(
      parsed.getScheme,
      parsed.getUserInfo,
      parsed.getHost,
      parsed.getPort,
      parsed.getPath,
      parsed.getQuery,
      parsed.getFragment
    ).toString
  }
}

object AuthRoutes {

  val routes: Route = concat(
    path("oauth" / "login") {
      get {
        parameters("redirect_uri", "client_context".optional) { (redirectUri, clientContext) =>
          if (RedirectValidator.isAllowedRedirect(redirectUri)) {
            val state = StateManager.createState(redirectUri)
            val authUrl = buildAuthorizationUrl(redirectUri, state)
            redirect(Uri(authUrl), StatusCodes.Found)
          } else {
            complete(StatusCodes.BadRequest, "Invalid redirect URI")
          }
        }
      }
    },
    path("oauth" / "callback") {
      get {
        parameters("code", "state") { (code, state) =>
          StateManager.validateAndConsume(state) match {
            case Some(oauthState) =>
              // Exchange code for token (simplified)
              val sessionToken = exchangeCodeForSession(code)
              val finalRedirect = appendSessionToRedirect(oauthState.redirectUri, sessionToken)
              redirect(Uri(finalRedirect), StatusCodes.Found)
            case None =>
              complete(StatusCodes.Forbidden, "Invalid or expired state")
          }
        }
      }
    },
    path("oauth" / "cross-service") {
      get {
        parameters("target_service", "session_token") { (targetService, sessionToken) =>
          if (validateSessionToken(sessionToken)) {
            val serviceRedirect = resolveServiceRedirect(targetService)
            serviceRedirect match {
              case Some(url) =>
                val crossToken = generateCrossServiceToken(sessionToken, targetService)
                redirect(Uri(s"$url?cross_token=$crossToken"), StatusCodes.Found)
              case None =>
                complete(StatusCodes.BadRequest, "Unknown target service")
            }
          } else {
            complete(StatusCodes.Unauthorized, "Invalid session")
          }
        }
      }
    }
  )

  private def buildAuthorizationUrl(redirectUri: String, state: String): String = {
    val encodedRedirect = URLEncoder.encode(
      s"https://chat.internal.corp/oauth/callback",
      StandardCharsets.UTF_8.name()
    )
    s"${OAuthConfig.authorizationEndpoint}?client_id=${OAuthConfig.clientId}&redirect_uri=$encodedRedirect&state=$state&response_type=code&scope=openid+profile"
  }

  private def exchangeCodeForSession(code: String): String = {
    // In production, this calls the token endpoint
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(OAuthConfig.hmacSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"))
    Base64.getUrlEncoder.withoutPadding().encodeToString(
      mac.doFinal(s"session:${System.currentTimeMillis()}:$code".getBytes(StandardCharsets.UTF_8))
    )
  }

  private def appendSessionToRedirect(redirectUri: String, sessionToken: String): String = {
    val separator = if (redirectUri.contains("?")) "&" else "?"
    s"$redirectUri${separator}session_token=${URLEncoder.encode(sessionToken, StandardCharsets.UTF_8.name())}"
  }

  private def validateSessionToken(token: String): Boolean = {
    token != null && token.nonEmpty && token.length > 20
  }

  private def resolveServiceRedirect(targetService: String): Option[String] = {
    val serviceRegistry = Map(
      "realtime" -> "https://realtime.internal.corp/auth/receive",
      "websocket" -> "https://ws.internal.corp/auth/receive",
      "chat" -> "https://chat.internal.corp/auth/receive"
    )
    serviceRegistry.get(targetService)
  }

  private def generateCrossServiceToken(sessionToken: String, targetService: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    mac.init(new SecretKeySpec(OAuthConfig.hmacSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"))
    val payload = s"cross:$sessionToken:$targetService:${System.currentTimeMillis()}"
    Base64.getUrlEncoder.withoutPadding().encodeToString(mac.doFinal(payload.getBytes(StandardCharsets.UTF_8)))
  }
}
